notify-slack:
  runs-on: ubuntu-latest
  needs: [release]
  if: ${{ failure() }}
  steps:
    - name: Notify Slack of release failure
      uses: slackapi/slack-github-action@91efab103c0de0a537f72a35f6b8cda0ee76bf0a # v2.1.1
      with:
        webhook: ${{ secrets.E2E_SLACK_WEBHOOK_URL }}
        webhook-type: incoming-webhook
        payload: |
          {
            "blocks": [
              {
                "type": "section",
                "text": {
                  "type": "mrkdwn",
                  "text": ":red_circle: *Release Failed* for `${{ github.ref_name }}`\n\n<${{ github.server_url }}/${{ github.repository }}/actions/runs/${{ github.run_id }}|View run details>"
                }
              },
              {
                "type": "context",
                "elements": [
                  {
                    "type": "mrkdwn",
                    "text": "Tag: `${{ github.ref_name }}` by ${{ github.actor }}"
                  }
                ]
              }
            ]
          }
